cat << 'EOF' > fix-lines.js
const fs = require('fs');

const updateFile = (file) => {
  let content = fs.readFileSync(file, 'utf8');
  content = content.replace(/chatOrchestrator\.test\.ts#L(\d+)/g, (match, p1) => {
    const line = parseInt(p1, 10);
    if (line > 300) {
      return `chatOrchestrator.test.ts#L${line + 8}`;
    }
    return match;
  });
  fs.writeFileSync(file, content);
};

updateFile('specs/hal-engine-architecture/spec.md');
updateFile('specs/hal-engine-config-hooks/spec.md');
updateFile('specs/hal-engine-tool-input-validation/spec.md');
EOF
node fix-lines.js
